defaultOptionValue:
{{
  (() => {
    // 1. On regarde quelle machine est actuellement sélectionnée
    const machineId = sel_interv_machine.selectedOptionValue;
    if (!machineId) return "";

    // 2. On cherche cette machine dans les données ramenées par la base
    const machines = Get_Machines_Client.data || [];
    const machineTrouvee = machines.find(m => m.ID_Machine === machineId);

    if (machineTrouvee && machineTrouvee.Categorie_Materiel) {
       // Petite sécurité : si la base renvoie "ROBOT" tout en majuscule, on le transforme en "Robot" pour que ça corresponde à l'option de ton bouton.
       let categorie = machineTrouvee.Categorie_Materiel;
       if (categorie.toUpperCase() === "ROBOT") return "Robot";

       return categorie; // Renvoie "2T" ou "4T"
    }

    return "";
  })()
}}
